package com.bank.parse;

import java.util.*;
import java.util.logging.*;

public class StaticRefDemo {
    private static final Logger log = Logger.getLogger("Parse");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> raw = List.of("10", "25", "7");
        ParseService service = new ParseService();

        log.info(() -> "parsed: " + service.toInts(raw));
        log.info(() -> "sum   : " + service.sum(raw));
    }
}

// ─── Would be in service/ParseService.java ───
class ParseService {
    List<Integer> toInts(List<String> raw) {
        return raw.stream()
            .map(Integer::parseInt)      // String → Integer (static ref)
            .toList();
    }
    int sum(List<String> raw) {
        return raw.stream()
            .mapToInt(Integer::parseInt) // String → int (primitive, no boxing)
            .sum();
    }
}
